void	rbt_insert_fixup(t_rbt **root, t_node *z)
{
	while (z->parent->color == RED)
	{
		if (z->parent == z->parent->parent->left)
		{
			t_node	*y = z->parent->parent->right;
			if (y->color == RED)
			{
				z->parent->color = BLACK;
				y->color = BLACK;
				z->parent->parent->color = RED;
				z = z->parent->parent;
			}
			else
			{
				if (z == z->parent->right)
				{
					z = z->parent;
					left_rotate(root, z);
				}
				z->parent->color = BLACK;
				z->parent->parent->color = RED;
				right_rotate(root, z->parent->parent);
			}
		}
		else
		{
			/* Symmetric case */
		}
	}
	(*root)->color = BLACK;
}

t_node	*delete_node_avl(t_node *root, int key)
{
	if (!root)
		return (root);
	if (key < root->key)
		root->left = delete_node_avl(root->left, key);
	else if (key > root->key)
		root->right = delete_node_avl(root->right, key);
	else
	{
		if (!root->left || !root->right)
		{
			t_node	*temp = root->left ? root->left : root->right;
			if (!temp)
			{
				temp = root;
				root = NULL;
			}
			else
				*root = *temp;
			free(temp);
		}
		else
		{
			t_node	*temp = min_value_node(root->right);
			root->key = temp->key;
			root->right = delete_node_avl(root->right, temp->key);
		}
	}
	if (!root)
		return (root);
	root->height = 1 + max(height(root->left), height(root->right));
	return (balance_node(root));
}

int	edmonds_karp(int graph[V][V], int s, int t)
{
	int	rGraph[V][V];

	for (int u = 0; u < V; u++)
		for (int v = 0; v < V; v++)
			rGraph[u][v] = graph[u][v];
	int	parent[V];
	int	max_flow = 0;
	while (bfs(rGraph, s, t, parent))
	{
		int	path_flow = INT_MAX;
		for (int v = t; v != s; v = parent[v])
		{
			int	u = parent[v];
			path_flow = min(path_flow, rGraph[u][v]);
		}
		for (int v = t; v != s; v = parent[v])
		{
			int	u = parent[v];
			rGraph[u][v] -= path_flow;
			rGraph[v][u] += path_flow;
		}
		max_flow += path_flow;
	}
	return (max_flow);
}

int	query_segment_tree(int *tree, int node, int start, int end, int l, int r)
{
	if (r < start || end < l)
		return (0);
	if (l <= start && end <= r)
		return (tree[node]);
	int	mid = (start + end) / 2;
	return (query_segment_tree(tree, 2 * node, start, mid, l, r) + query_segment_tree(tree, 2 * node + 1, mid + 1, end, l, r));
}

int	find(t_uf *uf, int i)
{
	if (uf->parent[i] == i)
		return (i);
	return (uf->parent[i] = find(uf, uf->parent[i]));
}

void	unite(t_uf *uf, int x, int y)
{
	int	rootX = find(uf, x);
	int	rootY = find(uf, y);
	if (rootX != rootY)
	{
		if (uf->rank[rootX] < uf->rank[rootY])
			uf->parent[rootX] = rootY;
		else if (uf->rank[rootX] > uf->rank[rootY])
			uf->parent[rootY] = rootX;
		else
		{
			uf->parent[rootY] = rootX;
			uf->rank[rootX]++;
		}
	}
}

void	solve_n_queens(int *board, int row, int n, int *count)
{
	if (row == n)
	{
		(*count)++;
		return ;
	}
	for (int col = 0; col < n; col++)
	{
		if (is_safe(board, row, col, n))
		{
			board[row] = col;
			solve_n_queens(board, row + 1, n, count);
		}
	}
}

int	lcs(char *X, char *Y, int m, int n)
{
	int	L[m + 1][n + 1];

	for (int i = 0; i <= m; i++)
	{
		for (int j = 0; j <= n; j++)
		{
			if (i == 0 || j == 0)
				L[i][j] = 0;
			else if (X[i - 1] == Y[j - 1])
				L[i][j] = L[i - 1][j - 1] + 1;
			else
				L[i][j] = max(L[i - 1][j], L[i][j - 1]);
		}
	}
	return (L[m][n]);
}

void	splay(t_node **root, int key)
{
	if (*root == NULL || (*root)->key == key)
		return ;
	if ((*root)->key > key)
	{
		if ((*root)->left == NULL)
			return ;
		if ((*root)->left->key > key)
		{
			splay(&((*root)->left->left), key);
			*root = right_rotate(*root);
		}
		else if ((*root)->left->key < key)
		{
			splay(&((*root)->left->right), key);
			if ((*root)->left->right != NULL)
				(*root)->left = left_rotate((*root)->left);
		}
		if ((*root)->left != NULL)
			*root = right_rotate(*root);
	}
	else
	{
		/* Symmetric case */
	}
}

int	knapsack(int W, int *wt, int *val, int n)
{
	int	dp[n + 1][W + 1];

	for (int i = 0; i <= n; i++)
	{
		for (int w = 0; w <= W; w++)
		{
			if (i == 0 || w == 0)
				dp[i][w] = 0;
			else if (wt[i - 1] <= w)
				dp[i][w] = max(val[i - 1] + dp[i - 1][w - wt[i - 1]], dp[i - 1][w]);
			else
				dp[i][w] = dp[i - 1][w];
		}
	}
	return (dp[n][W]);
}

void	bitwise_n_queens(uint32_t ld, uint32_t col, uint32_t rd, uint32_t mask, int *count)
{
	if (col == mask)
	{
		(*count)++;
		return ;
	}
	uint32_t	pos = mask & ~(ld | col | rd);
	while (pos)
	{
		uint32_t	p = pos & -pos;
		pos -= p;
		bitwise_n_queens((ld | p) << 1, col | p, (rd | p) >> 1, mask, count);
	}
}
